#!/usr/bin/env node
// Emits only the Open Props values the design uses, copied from the pinned package, so unused
// curves never ship. Regenerate with `pnpm design:open-props` after adding a name to SELECTED.
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import OpenProps from 'open-props';

// --ease-out-3 equals the incumbent storefront's cubic-bezier(0, 0, .3, 1).
export const SELECTED = ['--ease-out-3'];

export function renderOpenPropsCss() {
 return [
  '/* Generated by scripts/design/open-props.mjs from open-props — do not edit by hand. */',
  '@layer tokens {',
  ' :root {',
  ...SELECTED.map(name => {
   if (!(name in OpenProps)) throw new Error(`Unknown Open Props value: ${name}`);
   return `  ${name}: ${OpenProps[name]};`;
  }),
  ' }',
  '}',
  '',
 ].join('\n');
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
 const target = new URL('../../src/styles/global/open-props.css', import.meta.url);
 writeFileSync(target, renderOpenPropsCss());
 console.log(`Wrote ${fileURLToPath(target)}`);
}
